/** @type {Record<string, Record<string, string>>} */
const BUNDLES = {
	[ZH_TW]: ZH,
	en: EN,
	ja: JA,
	ko: KO,
	vi: VI,
	th: TH,
	id: ID,
};

/**
 * @param {string} locale
 * @param {string} key
 * @returns {string | undefined}
 */
export function lookupFrontendStatic(locale, key) {
	if (typeof key !== "string" || !key) return undefined;
	const chain = [locale, "en", ZH_TW];
	const tried = new Set();
	for (const loc of chain) {
		if (tried.has(loc)) continue;
		tried.add(loc);
		const pack = BUNDLES[loc];
		if (!pack || !Object.prototype.hasOwnProperty.call(pack, key)) {
			continue;
		}
		const v = pack[key];
		if (v !== undefined && v !== null && v !== "") {
			return v;
		}
	}
	return undefined;
}
